/*
 * A290885  Let S be the sequence generated by these rules: 0 is in S, and if
 *          z is in S, then z * (1+i) and (z-1) * (1+i) + 1 are in S (where i
 *          denotes the imaginary unit), and duplicates are deleted as they
 *          occur; a(n) = the imaginary part of the n-th term of S.
 * https://oeis.org/A290885
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  sign, look
 * Formula:   A290885 – imaginary part of the nth complex integer obtained by
 *            a breadth‑first traversal of the tree z → z*(1+i) and z →
 *            (z-1)*(1+i)+1, starting from 0, with duplicate nodes discarded
 * Range:     i8 n <= 10000, i16 n <= 10000, i32 n <= 10000, i64 n <= 10000,
 *            i128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>

typedef struct {
    seq_t r;    /* real part */
    seq_t i;    /* imaginary part */
} complex_t;

/* static storage for the sequence (thread‑safe assumption)
   S holds all discovered Gaussian integers in order of appearance   */
static complex_t *S = NULL;
static size_t S_len = 0;   /* number of elements actually stored   */
static size_t S_cap = 0;   /* size of allocated buffer             */

/* Ensure that at least `needed` elements can be stored. */
static void ensure_capacity(size_t needed)
{
    if (needed <= S_cap)
        return;
    size_t new_cap = S_cap ? S_cap * 2 : 1024;
    if (new_cap < needed)
        new_cap = needed;
    complex_t *newp = (complex_t *)realloc(S, new_cap * sizeof(complex_t));
    S = newp;
    S_cap = new_cap;
}

/* Equality test for two complex numbers. */
static bool eq_complex(const complex_t *a, const complex_t *b)
{
    return a->r == b->r && a->i == b->i;
}

/* Return true if `node` is already present in S. */
static bool contains(const complex_t *node)
{
    for (size_t j = 0; j < S_len; ++j)
        if (eq_complex(&S[j], node))
            return true;
    return false;
}

/* Append a new node at the end of S, unless it is a duplicate. */
static void add_node(const complex_t *node)
{
    if (!contains(node)) {
        ensure_capacity(S_len + 1);
        S[S_len++] = *node;
    }
}

seq_t a(idx_t n)
{
    if (n == 0)                     /* offset is 1 – safety check   */
        return 0;

    size_t target = (size_t)n;      /* required number of elements  */

    /* initialise the sequence with the root 0 when first called   */
    if (S_len == 0) {
        complex_t root = { (seq_t)0, (seq_t)0 };
        add_node(&root);
    }

    /* breadth‑first generation until we have `target` elements   */
    size_t idx = 0;
    while (S_len < target) {
        if (idx >= S_len)   /* safety, should not happen      */
            break;
        complex_t cur = S[idx];

        /* child f(z) = z*(1+i)  ->  (a-b) + (a+b)i   */
        complex_t f;
        f.r = cur.r - cur.i;
        f.i = cur.r + cur.i;
        add_node(&f);

        /* child g(z) = (z-1)*(1+i)+1
           ->  (a-b) + ((a-1)+b)i                  */
        complex_t g;
        g.r = cur.r - cur.i;
        g.i = cur.r - (seq_t)1 + cur.i;
        add_node(&g);

        ++idx;
    }

    return S[n-1].i;   /* return the imaginary part of the nth element */
}
